namespace Erlang;

internal static class DistributionHandleLayout
{
    internal const int Arity = 2;
    internal const int ConnectionIdIndex = 0;
    internal const int ReferenceIndex = 1;
    internal const int ConnectionIdBits = 24;
    internal const uint ConnectionIdMask = (1u << ConnectionIdBits) - 1;
    internal const int NativeSmallMagnitudeBits = 59;
    internal const long NativeSmallMinimum = -(1L << NativeSmallMagnitudeBits);
    internal const long NativeSmallMaximum = (1L << NativeSmallMagnitudeBits) - 1;
}

namespace Erlang;

internal static class DistributionNodeIdentity
{
    private const char Separator = '@';

    internal static bool IsValid(Atom node)
    {
        int separator = node.Name.IndexOf(Separator);
        if (separator <= 0 || separator == node.Name.Length - 1 || node.Name.IndexOf(Separator, separator + 1) >= 0)
            return false;
        for (int index = 0; index < separator; index++)
            if (node.Name[index] is not ('-' or '_' or >= 'a' and <= 'z' or >= 'A' and <= 'Z' or >= '0' and <= '9'))
                return false;

        return true;
    }
}

namespace Erlang;

internal static class DistributionPendingDiagnostics
{
    internal const string Closed = "The runtime pending distribution table is closed";
    internal const string Handle = "The pending distribution handle is foreign, malformed or stale";
    internal const string Node = "A pending distribution node must have a valid remote node identity";
    internal const string Capacity = "The runtime pending distribution node budget is exhausted";
    internal const string AlreadyInitialized = "The runtime pending distribution table is already initialized";
    internal const string Process = "The setup process is not a live owner in this runtime";
    internal const string Kernel = "A live registered kernel setup reservation is required";
    internal const string Controller = "The process or pending entry already has a setup role";
    internal const string ResourceOwner = "The distribution entry belongs to another reference resource owner";
    internal const string Lease = "The pending distribution lease is disposed";
}

namespace Erlang;

public sealed class DistributionPendingLease : IDisposable
{
    private ReferenceResourceLease<RuntimeDistributionPendingEntry>? lease;
    private readonly uint connectionId;

    internal DistributionPendingLease(ReferenceResourceLease<RuntimeDistributionPendingEntry> lease, uint connectionId)
    {
        this.lease = lease;
        this.connectionId = connectionId;
    }

    public DistributionPendingSnapshot Snapshot()
    {
        var current = Volatile.Read(ref lease) ?? throw new ObjectDisposedException(DistributionPendingDiagnostics.Lease);
        var entry = current.Value;

        return entry.Owner.SnapshotEntry(entry, connectionId);
    }

    public void Dispose() => Interlocked.Exchange(ref lease, null)?.Dispose();
}

namespace Erlang;

internal static class DistributionPendingParameters
{
    internal const int DefaultMaximumNodes = 1024;
}

namespace Erlang;

public sealed record DistributionPendingSnapshot(
    Atom RemoteNode,
    uint ConnectionId,
    DistributionPendingState State,
    Pid? ReservedController,
    Pid? ReservedKernel
);

namespace Erlang;

public enum DistributionPendingState
{
    Idle,
    Pending,
    Closed
}

